pub const fn mordekaiser_p1(ctx: &Ctx) -> f32 {
    3f32 * (0.1 * ctx.ability_power + ctx.level)
}

pub const fn mordekaiser_p2(ctx: &Ctx) -> f32 {
    ctx.enemy_max_health * (0.01 + 0.0024 * (-1f32 + ctx.level))
}

pub const fn mordekaiser_p3(ctx: &Ctx) -> f32 {
    0.0375 * ctx.ability_power
}

pub const fn mordekaiser_p4(ctx: &Ctx) -> f32 {
    ctx.enemy_max_health * (0.0013 + 0.0002 * (-1f32 + ctx.level))
}

pub const fn mordekaiser_p5(ctx: &Ctx) -> f32 {
    0.03 * ctx.bonus_move_speed
}

pub const fn mordekaiser_p6(ctx: &Ctx) -> f32 {
    0.03 * ctx.bonus_move_speed
}

pub const fn mordekaiser_p7(ctx: &Ctx) -> f32 {
    ctx.enemy_max_health * (0.01 + 0.0024 * (-1f32 + ctx.level))
}

pub const fn mordekaiser_p8(ctx: &Ctx) -> f32 {
    ctx.enemy_max_health * (0.0013 + 0.0002 * (-1f32 + ctx.level))
}

pub const fn mordekaiser_p1min(ctx: &Ctx) -> f32 {
    40f32 + 9.41 * (-1f32 + ctx.level)
}

pub const fn mordekaiser_q1(ctx: &Ctx) -> f32 {
    5f32 * (5f32 + ctx.q_level)
}

pub const fn mordekaiser_q2(ctx: &Ctx) -> f32 {
    80f32
        + (match ctx.level as u8 {
            ..10 => 0f32,
            10 => 5f32,
            11 => 10f32,
            12 => 15f32,
            13 => 20f32,
            14 => 25f32,
            15 => 30f32,
            16 => 35f32,
            17 => 40f32,
            18 => 45f32,
            19 => 50f32,
            20.. => 55f32,
        })
        + 0.7 * ctx.ability_power
        + 1.2 * ctx.bonus_ad
        + 35f32 * (-1f32 + ctx.q_level)
}

pub const fn mordekaiser_e1(ctx: &Ctx) -> f32 {
    15f32 * (3f32 + 0.026666666667 * ctx.ability_power + ctx.e_level)
}

