pub const fn syndra_q1(ctx: &Ctx) -> f32 {
    5f32 * (16f32 + 0.13 * ctx.ability_power + 7f32 * (-1f32 + ctx.q_level))
}

pub const fn syndra_w1(ctx: &Ctx) -> f32 {
    8.4 + 3.6 * (-1f32 + ctx.w_level)
        + ctx.ability_power * (0.092 + 0.006 * (-1f32 + ctx.w_level))
}

